namespace g=cp::geometry;namespace e=g::exact;namespace f=g::floating;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class E,class F>void rejects(F fn){bool caught=false;try{fn();}catch(const E&){caught=true;}require(caught,"missing exception");}
long long det(e::Point a,e::Point b,e::Point c){return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);}
long long d2(e::Point a,e::Point b){return (a.x-b.x)*(a.x-b.x)+(a.y-b.y)*(a.y-b.y);}
bool on(e::Point a,e::Point b,e::Point p){return !det(a,b,p)&&std::min(a.x,b.x)<=p.x&&p.x<=std::max(a.x,b.x)&&std::min(a.y,b.y)<=p.y&&p.y<=std::max(a.y,b.y);}
bool intersects(e::Point a,e::Point b,e::Point c,e::Point d){const long long den=(b.x-a.x)*(d.y-c.y)-(b.y-a.y)*(d.x-c.x);if(!den)return on(a,b,c)||on(a,b,d)||on(c,d,a)||on(c,d,b);const e::Rational t((c.x-a.x)*(d.y-c.y)-(c.y-a.y)*(d.x-c.x),den),u((c.x-a.x)*(b.y-a.y)-(c.y-a.y)*(b.x-a.x),den);return !(t<e::Rational(0))&&!(e::Rational(1)<t)&&!(u<e::Rational(0))&&!(e::Rational(1)<u);}
std::vector<e::Point> jarvis(std::vector<e::Point>p){std::sort(p.begin(),p.end());p.erase(std::unique(p.begin(),p.end()),p.end());if(p.size()<2)return p;std::vector<e::Point>h;std::size_t at=0;do{h.push_back(p[at]);std::size_t next=(at+1)%p.size();for(std::size_t j=0;j<p.size();++j)if(j!=at){const auto turn=det(p[at],p[next],p[j]);if(turn<0||(!turn&&d2(p[at],p[j])>d2(p[at],p[next])))next=j;}at=next;}while(at);return h;}
g::Location ray(const std::vector<e::Point>&p,e::Point q){bool inside=false;for(std::size_t i=0;i<p.size();++i){auto a=p[i],b=p[(i+1)%p.size()];if(on(a,b,q))return g::Location::boundary;if((a.y>q.y)!=(b.y>q.y)){e::Rational x=e::Rational(a.x)+e::Rational(b.x-a.x)*e::Rational(q.y-a.y,b.y-a.y);if(e::Rational(q.x)<x)inside=!inside;}}return inside?g::Location::inside:g::Location::outside;}
std::vector<f::Point> floating(const std::vector<e::Point>&p){std::vector<f::Point>q;for(auto a:p)q.push_back(g::to_floating(a));return q;}
void rational(){std::size_t cases=0;for(int a=-8;a<=8;++a)for(int b=1;b<=8;++b)for(int c=-8;c<=8;++c)for(int d=1;d<=8;++d){e::Rational x(a,b),y(c,d);require((x<y)==(a*d<c*b),"rational continued-fraction order");require((x+y)==e::Rational(a*d+c*b,b*d)&&x-y==e::Rational(a*d-c*b,b*d)&&x*y==e::Rational(a*c,b*d),"rational exact arithmetic");if(c)require(x/y==e::Rational(a*d,b*c),"rational exact division");++cases;}
 const e::Wide hi=e::Wide((e::UWide(1)<<127)-1),lo=-hi-1;require(e::Rational(hi-1,hi)<e::Rational(hi,hi-1),"rational comparison avoids overflow");require(e::Rational(hi,hi-1)*e::Rational(hi-1,hi)==e::Rational(1),"rational cross cancellation");require(e::to_string(lo)=="-170141183460469231731687303715884105728","minimum wide printing");rejects<std::overflow_error>([&]{e::Rational(hi)+e::Rational(1);});rejects<std::overflow_error>([&]{e::arithmetic::mul(hi,2);});rejects<std::domain_error>([]{e::Rational(1,0);});rejects<std::domain_error>([]{e::Rational(1)/e::Rational(0);});std::cout<<cases<<" rational pairs and 128-bit limits passed\n";}
void grid_primitives(){std::vector<e::Point>grid;for(int x=-1;x<=1;++x)for(int y=-1;y<=1;++y)grid.push_back({x,y});std::size_t triples=0,segments=0;for(auto a:grid)for(auto b:grid)for(auto c:grid){const auto z=det(a,b,c);const auto dp=(b.x-a.x)*(c.x-a.x)+(b.y-a.y)*(c.y-a.y);const int answer=z>0?1:z<0?-1:dp<0?2:d2(a,c)>d2(a,b)?-2:0;require(static_cast<int>(e::ccw(a,b,c))==answer&&static_cast<int>(f::ccw(g::to_floating(a),g::to_floating(b),g::to_floating(c),f::Tolerance(0)))==answer,"all five CCW cases");++triples;}
 for(auto a:grid)for(auto b:grid)for(auto c:grid)for(auto d:grid){const bool want=intersects(a,b,c,d);require(e::segments_intersect({a,b},{c,d})==want,"segment parameter intersection");require(f::segments_intersect({g::to_floating(a),g::to_floating(b)},{g::to_floating(c),g::to_floating(d)},f::Tolerance(0))==want,"floating exact-grid intersection");if(want)require(e::squared_distance(e::Segment{a,b},e::Segment{c,d})==e::Rational(0),"intersecting segments have zero distance");++segments;}
 const auto cross=e::line_intersection(e::Line({0,0},{3,3}),e::Line({0,2},{4,0}));require(cross.relation==g::LineRelation::unique&&cross.point->x==e::Rational(4,3)&&cross.point->y==e::Rational(4,3),"rational line intersection");require(e::line_intersection(e::Line({0,0},{1,1}),e::Line({0,1},{1,2})).relation==g::LineRelation::parallel,"parallel distinct lines");require(e::line_intersection(e::Line({0,0},{1,1}),e::Line({3,3},{1,1})).relation==g::LineRelation::coincident,"coincident lines");const auto p=e::projection(e::Line({0,0},{2,1}),{1,2});require(p==e::RationalPoint(e::Rational(8,5),e::Rational(4,5)),"exact projection");require(e::squared_distance(e::Line({0,0},{2,1}),e::Point{1,2})==e::Rational(9,5),"rational perpendicular squared distance");require(e::squared_distance(e::Segment{{0,0},{1,0}},e::Point{2,1})==e::Rational(2)&&e::squared_distance(e::Segment{{0,0},{0,0}},e::Point{2,1})==e::Rational(5),"segment endpoint and point distance");std::cout<<triples<<" CCW triples / "<<segments<<" segment quadruples, degeneracies and rational constructions passed\n";}
void line_distances(){const e::Line a({0,0},{2,0}),b({0,3},{1,3}),c({0,0},{1,1});const e::Segment s{{0,2},{2,4}},touch{{0,-1},{0,1}};require(e::squared_distance(a,b)==e::Rational(9)&&e::squared_distance(a,c)==e::Rational(0),"line-line distance");require(e::squared_distance(a,s)==e::Rational(4)&&e::squared_distance(s,a)==e::Rational(4)&&e::squared_distance(a,touch)==e::Rational(0),"line-segment distance");require(e::squared_distance(e::Point{0,3},a)==e::Rational(9)&&e::squared_distance(e::Point{0,0},s)==e::Rational(4),"symmetric exact distances");const f::Line fa({0,0},{2,0}),fb({0,3},{1,3}),fc({0,0},{1,1});const f::Segment fs{{0,2},{2,4}},ft{{0,-1},{0,1}};require(f::distance(fa,fb)==3&&f::distance(fa,fc)==0&&f::distance(fa,fs)==2&&f::distance(fs,fa)==2&&f::distance(fa,ft)==0&&f::distance(f::Point{0,3},fa)==3&&f::distance(f::Point{0,0},fs)==2,"floating symmetric line/segment distances");}
void hulls(){std::vector<e::Point>grid;for(int x=-1;x<=1;++x)for(int y=-1;y<=1;++y)grid.push_back({x,y});for(int mask=0;mask<512;++mask){std::vector<e::Point>p;for(int i=0;i<9;++i)if(mask>>i&1)p.push_back(grid[i]);auto h=e::convex_hull(p);require(h==jarvis(p),"hull vs independent gift wrapping");auto hf=f::convex_hull(floating(p),false,f::Tolerance(0));require(hf==floating(h),"floating hull exact grid");e::ConvexPolygon polygon(p);f::ConvexPolygon fp(floating(p),f::Tolerance(0));for(int x=-2;x<=2;++x)for(int y=-2;y<=2;++y){const e::Point q{x,y};auto want=ray(h,q);require(e::point_in_polygon(h,q)==want&&e::convex_polygon_contains(h,q)==want&&polygon.contains(q)==want,"winding / binary fan vs rational ray");require(f::point_in_polygon(hf,g::to_floating(q),f::Tolerance(0))==want&&fp.contains(g::to_floating(q))==want,"floating containment grid");}auto boundary=e::convex_hull(p,true);std::set<std::pair<long long,long long>>want;for(auto q:p){bool belongs=h.size()<2;for(std::size_t i=0;i<h.size();++i)if(on(h[i],h[(i+1)%h.size()],q))belongs=true;if(belongs)want.insert({q.x,q.y});}std::set<std::pair<long long,long long>>got;for(auto q:boundary)got.insert({q.x,q.y});require(got==want&&got.size()==boundary.size(),"keep boundary collinear points once");}
 std::vector<e::Point>concave{{0,0},{4,0},{4,1},{1,1},{1,4},{0,4}};for(int r=0;r<2;++r){for(int x=-1;x<=5;++x)for(int y=-1;y<=5;++y)require(e::point_in_polygon(concave,{x,y})==ray(concave,{x,y}),"concave and CW winding");std::reverse(concave.begin(),concave.end());}std::cout<<"512 point subsets: Jarvis hulls, all boundary points and 12800 containment queries; concave/CW polygons passed\n";}
void cuts(std::mt19937_64&rng){std::size_t count=0;for(int trial=0;trial<300;++trial){std::vector<e::Point>p;for(int i=0;i<15;++i)p.push_back({static_cast<long long>(rng()%11)-5,static_cast<long long>(rng()%11)-5});auto h=e::convex_hull(p);e::Point a{static_cast<long long>(rng()%15)-7,static_cast<long long>(rng()%15)-7},b{static_cast<long long>(rng()%15)-7,static_cast<long long>(rng()%15)-7};if(a==b)b.x++;e::Line line(a,b);auto cut=e::convex_polygon_cut(h,line);std::vector<e::RationalPoint>candidates;for(auto v:h)if(det(a,b,v)>=0)candidates.emplace_back(v);for(std::size_t i=0;i<h.size();++i){const auto u=h[i],v=h[(i+1)%h.size()];const auto s=det(a,b,u),t=det(a,b,v);if((s<0&&t>0)||(s>0&&t<0))candidates.push_back(e::RationalPoint(u)+(e::RationalPoint(v)-e::RationalPoint(u))*e::Rational(s,s-t));}for(const auto&q:cut)require(std::find(candidates.begin(),candidates.end(),q)!=candidates.end(),"cut vertex comes from original vertices or edge-line intersection");for(const auto&q:candidates)require(std::find(cut.begin(),cut.end(),q)!=cut.end(),"cut includes every boundary candidate");require(!(e::polygon_area(h)<e::polygon_area(cut)),"cut cannot increase area");auto fc=f::convex_polygon_cut(floating(h),f::Line(g::to_floating(a),g::to_floating(b)),f::Tolerance(0));require(std::abs(f::polygon_area(fc)-e::polygon_area(cut).approximate())<1e-8L,"floating/exact rational cut area");++count;}
 const std::vector<e::Point>square{{0,0},{2,0},{2,2},{0,2}};auto q=e::convex_polygon_cut(square,e::Line({0,1},{3,0}));require(e::polygon_area(q)==e::Rational(8,3),"fractional area after cut");q=e::convex_polygon_cut(q,e::Line({1,0},{1,1}));require(e::polygon_area(q)==e::Rational(7,6),"repeat cut remains rational");require(e::convex_polygon_cut(square,e::Line({-1,0},{-1,1})).empty(),"empty cut");std::cout<<count<<" convex cuts by candidate vertex sets, areas and repeated rational cuts passed\n";}
void pairs(std::mt19937_64&rng){for(int trial=0;trial<600;++trial){std::vector<e::Point>p(rng()%45);for(auto&a:p)a={static_cast<long long>(rng()%101)-50,static_cast<long long>(rng()%101)-50};auto result=e::closest_pair(p);auto fresult=f::closest_pair(floating(p));require(bool(result)==(p.size()>=2)&&bool(fresult)==bool(result),"closest pair empty/single");if(result){long long minimum=std::numeric_limits<long long>::max();for(std::size_t i=0;i<p.size();++i)for(std::size_t j=i+1;j<p.size();++j)minimum=std::min(minimum,d2(p[i],p[j]));require(result->first<result->second&&result->second<p.size()&&result->squared_distance==minimum&&e::squared_distance(p[result->first],p[result->second])==minimum,"closest pair by all pairs and original indices");require(fresult->squared_distance==minimum,"floating closest squared distance");}auto h=e::convex_hull(p);auto diameter=e::convex_diameter(h);require(bool(diameter)==!h.empty(),"diameter empty");if(diameter){long long maximum=0;for(auto a:h)for(auto b:h)maximum=std::max(maximum,d2(a,b));require(diameter->squared_distance==maximum&&e::squared_distance(h[diameter->first],h[diameter->second])==maximum,"antipodal pairs vs all pairs");require(f::convex_diameter(floating(h))->squared_distance==maximum,"floating antipodal pairs");}}
 std::cout<<"600 point clouds: closest pair and rotating calipers vs every pair passed\n";}
struct CountKernel:e::Kernel{std::size_t*dist,*sides;CountKernel(std::size_t*d,std::size_t*s):dist(d),sides(s){}e::Wide distance2(e::Point a,e::Point b)const{++*dist;return e::squared_distance(a,b);}e::Wide side(e::Point a,e::Point b,e::Point c)const{++*sides;return e::cross(a,b,c);}};
void limits_and_large(){const auto hi=std::numeric_limits<std::int64_t>::max(),lo=std::numeric_limits<std::int64_t>::min();require(e::cross({lo,0},{hi,0},{lo,1})==e::Wide(e::UWide(1)<<64)-1,"subtract after widening");rejects<std::overflow_error>([&]{e::Point{hi,0}+e::Point{1,0};});rejects<std::overflow_error>([&]{e::squared_distance(e::Point{lo,0},e::Point{hi,0});});rejects<std::overflow_error>([&]{e::cross({lo,lo},{hi,lo},{lo,hi});});rejects<std::invalid_argument>([]{e::Line({1,1},{1,1});});rejects<std::invalid_argument>([]{f::Line({0,0},{0,0});});for(long double bad:{std::numeric_limits<long double>::infinity(),std::numeric_limits<long double>::quiet_NaN()}){rejects<std::invalid_argument>([&]{f::Point(bad,0);});rejects<std::invalid_argument>([&]{f::Tolerance t(bad);});}rejects<std::invalid_argument>([]{f::Tolerance t(-1);});f::Point mutated;mutated.x=std::numeric_limits<long double>::infinity();rejects<std::invalid_argument>([&]{mutated+f::Point{};});rejects<std::invalid_argument>([&]{mutated-f::Point{};});rejects<std::invalid_argument>([&]{mutated*1;});rejects<std::invalid_argument>([&]{mutated/1;});rejects<std::overflow_error>([]{f::dot({1e3000L,0},{1e3000L,0});});
 require(f::closest_pair({{0,0},{1e-12L,0}})->squared_distance>0,"closest metric does not use epsilon equality");require(f::orientation({0,0},{1,0},{0,1e-12L})==0&&f::orientation({0,0},{1,0},{0,1e-12L},f::Tolerance(0))==1,"explicit absolute epsilon");auto angle=f::angular_sort({{1,2e-13L},{1,0},{1,1e-13L}});require(angle[0].y==0&&angle[1].y==1e-13L,"angular sorting has no epsilon comparator");
 std::vector<e::Point>p;for(int i=0;i<200000;++i)p.push_back({3LL*i,0});std::size_t distances=0,sides=0;auto nearest=g::detail::closest(p,CountKernel(&distances,&sides));require(nearest->squared_distance==9&&distances<200*p.size(),"200000 closest points and n log n arithmetic bound");auto h=e::convex_hull(p);require(h.size()==2,"large collinear hull");p.clear();for(long long i=-10000;i<=10000;++i)p.push_back({i,i*i});h=e::convex_hull(p);distances=sides=0;auto farthest=g::detail::diameter(h,CountKernel(&distances,&sides));require(h.size()==20001&&farthest->squared_distance==e::Wide(10000)*10000*10000*10000+100000000&&sides<=20*h.size()&&distances<=8*h.size(),"20001-vertex calipers and linear operation bound");std::cout<<"200000-point closest / 20001-vertex calipers, numeric extremes, rejection and epsilon ordering passed\n";}
}
int main(){std::mt19937_64 rng(322022);rational();grid_primitives();line_distances();hulls();cuts(rng);pairs(rng);limits_and_large();}
